/**
 * @hidden
 */
const DEFAULT_VIRTUALIZATION_SETTINGS = {
    type: 'both',
    rowHeight: 37,
    rows: 50,
    columns: 10
};
/**
 * @hidden
 */
export const normalizeVirtualSettings = (settings) => {
    if (settings === true) {
        return { ...DEFAULT_VIRTUALIZATION_SETTINGS };
    }
    if (!settings) {
        return null;
    }
    return { ...DEFAULT_VIRTUALIZATION_SETTINGS, ...settings };
};
